function findUnsortedSubarray(nums) {
  const n = nums.length;
  let maxFromLeft = -Infinity;
  let minFromRight = Infinity;
  let start = 0;
  let end = -1;

  for (let left = 0; left < n; left++) {
    const right = n - 1 - left;
    maxFromLeft = Math.max(maxFromLeft, nums[left]);
    if (nums[left] < maxFromLeft) {
      end = left;
    }
    minFromRight = Math.min(minFromRight, nums[right]);
    if (nums[right] > minFromRight) {
      start = right;
    }
  }
  return end - start + 1;
}

