function findUnsortedSubarray(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  let first = -1;
  let last = -1;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== sorted[i]) {
      if (first === -1) first = i;
      last = i;
    }
  }
  return first === -1 ? 0 : last - first + 1;
}

