function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const span = int(1, 6);
    const nums = Array.from({ length: n }, () => int(-span, span));
    if (rand() < 0.35) nums.sort((a, b) => a - b);
    if (rand() < 0.3 && n >= 2) {
      const i = int(0, n - 1), j = int(0, n - 1);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    return [nums];
  }
  const n = 2000;
  const nums = Array.from({ length: n }, () => int(-100000, 100000)).sort((a, b) => a - b);
  const mode = int(0, 2);
  if (mode === 0) {
    // Shuffle one inner block.
    const a = int(0, n - 1), b = int(a, n - 1);
    for (let i = b; i > a; i--) {
      const j = int(a, i);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  } else if (mode === 1) {
    // Swap two far-apart values.
    const i = int(0, n - 1), j = int(0, n - 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  } else {
    // Fully random.
    for (let i = n - 1; i > 0; i--) {
      const j = int(0, i);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
